package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.apache.commons.math3.exception.DimensionMismatchException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class OpenMapRealVector_ebeMultiply_TriageGen5Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testEbeMultiply_Success() {
        // Setup a sparse vector: [1.0, 0.0, 2.0, 0.0, 3.0]
        OpenMapRealVector v1 = new OpenMapRealVector(5);
        v1.setEntry(0, 1.0);
        v1.setEntry(2, 2.0);
        v1.setEntry(4, 3.0);

        // Setup multiplier vector: [10.0, 5.0, 2.0, 1.0, 0.5]
        double[] values = {10.0, 5.0, 2.0, 1.0, 0.5};
        RealVector v2 = new ArrayRealVector(values);

        // Expected: [1.0*10.0, 0.0, 2.0*2.0, 0.0, 3.0*0.5] = [10.0, 0.0, 4.0, 0.0, 1.5]
        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(5, result.getDimension());
        Assert.assertEquals(10.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(4.0, result.getEntry(2), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(3), EPSILON);
        Assert.assertEquals(1.5, result.getEntry(4), EPSILON);
    }

    @Test
    public void testEbeMultiply_EmptyVector() {
        OpenMapRealVector v1 = new OpenMapRealVector(3); // All zeros
        RealVector v2 = new ArrayRealVector(new double[]{1.0, 2.0, 3.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(3, result.getDimension());
        Assert.assertEquals(0.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(2), EPSILON);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testEbeMultiply_DimensionMismatch() {
        OpenMapRealVector v1 = new OpenMapRealVector(3);
        v1.setEntry(0, 1.0);

        RealVector v2 = new ArrayRealVector(new double[]{1.0, 2.0}); // Dimension 2 != 3

        v1.ebeMultiply(v2);
    }

    @Test
    public void testEbeMultiply_ZeroMultiplication() {
        OpenMapRealVector v1 = new OpenMapRealVector(2);
        v1.setEntry(0, 5.0);
        v1.setEntry(1, 10.0);

        RealVector v2 = new ArrayRealVector(new double[]{0.0, 0.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(0.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(1), EPSILON);
    }

    @Test
    public void testEbeMultiply_PreservesOriginal() {
        OpenMapRealVector v1 = new OpenMapRealVector(2);
        v1.setEntry(0, 2.0);

        RealVector v2 = new ArrayRealVector(new double[]{3.0, 3.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        // Check result
        Assert.assertEquals(6.0, result.getEntry(0), EPSILON);
        // Check original was not mutated
        Assert.assertEquals(2.0, v1.getEntry(0), EPSILON);
    }
}
